"},"directionIds":[],"name":{"uz":"CAU Tibbiyot va stomatologiya (M.D., D.D.S.) tayyorgarligi","ru":"CAU: подготовка — Медицина и стоматология (M.D., D.D.S.)","en":"CAU Medicine and Dentistry (M.D., D.D.S.) Preparation"},"description":{"uz":"CAU “Tibbiyot va stomatologiya (M.D., D.D.S.)” uçun rasmiy sahifada körsatilgan talablar böyiça tayyorgarlik. Kurslar — şu fanlar böyiça ILMORA oflayn kurslari; paket universitet bilan rasmiy boğliq emas.","ru":"Подготовка по требованиям, указанным на официальной странице CAU для «Медицина и стоматология (M.D., D.D.S.)». Курсы — офлайн-курсы ILMORA по этим предметам; пакет официально не связан с университетом.","en":"Preparation for the requirements CAU states on its official page for Medicine and Dentistry (M.D., D.D.S.). The courses are ILMORA offline courses for these subjects; the package is not officially affiliated with the university."},"slots":[{"id":"uni-cau-medicine-s1","label":{"uz":"Biologiya","ru":"Биология","en":"Biology"},"courseKey":null},{"id":"uni-cau-medicine-s2","label":{"uz":"Kimyo","ru":"Химия","en":"Chemistry"},"courseKey":"c-chemistry"},{"id":"uni-cau-medicine-s3","label":{"uz":"Ingliz tili (IELTS 6.0 yoki unga teng)","ru":"Английский язык (IELTS 6.0 или эквивалент)","en":"English (IELTS 6.0 or equivalent)"},"courseKey":"c-ielts"}],"admission":{"url":"https://centralasian.uz/admissionregulations","academicYear":"2027-2028","status":"verified","note":"Admission regulations: own Biology and Chemistry exams (20 questions / 45 min each, pass mark 50%) and English (IELTS 6.0 or TOEFL iBT 60 exempts). The Medicine and Dentistry pages cite both 2026-2027 and 2027-2028 intakes with the same subjects.","checkedOn":"2026-10-30"},"admissionOk":true},{"id":"uni-tuit-it","universityId":"uni-tuit","program":{"uz":"Dasturiy injiniring, sun’iy intellekt, kiberxavfsizlik, kompyuter injiniringi","ru":"Программная инженерия, ИИ, кибербезопасность, компьютерная инженерия","en":"Software Engineering, AI, Cybersecurity, Computer Engineering"},"directionIds":[],"name":{"uz":"TUIT Dasturiy injiniring, sun’iy intellekt, kiberxavfsizlik, kompyuter injiniringi tayyorgarligi","ru":"TUIT: подготовка — Программная инженерия, ИИ, кибербезопасность, компьютерная инженерия","en":"TUIT Software Engineering, AI, Cybersecurity, Computer Engineering Preparation"},"description":{"uz":"TUIT “Dasturiy injiniring, sun’iy intellekt, kiberxavfsizlik, kompyuter injiniringi” uçun rasmiy sahifada körsatilgan talablar böyiça tayyorgarlik. Kurslar — şu fanlar böyiça ILMORA oflayn kurslari; paket universitet bilan rasmiy boğliq emas.","ru":"Подготовка по требованиям, указанным на официальной странице TUIT для «Программная инженерия, ИИ, кибербезопасность, компьютерная инженерия». Курсы — офлайн-курсы ILMORA по этим предметам; пакет официально не связан с университетом.","en":"Preparation for the requirements TUIT states on its official page for Software Engineering, AI, Cybersecurity, Computer Engineering. The courses are ILMORA offline courses for these subjects; the package is not officially affiliated with the university."},"slots":[{"id":"uni-tuit-it-s1","label":{"uz":"Ona tili (özbek, rus yoki qoraqalpoq)","ru":"Родной язык (узбекский, русский или каракалпакский)","en":"Native language (Uzbek, Russian or Karakalpak)"},"courseKey":null},{"id":"uni-tuit-it-s2","label":{"uz":"Matematika (majburiy fan va yönaliş fani)","ru":"Математика (обязательный и профильный предмет)","en":"Mathematics (mandatory and direction subject)"},"courseKey":"c-algebra"},{"id":"uni-tuit-it-s3","label":{"uz":"Özbekiston tarixi","ru":"История Узбекистана","en":"History of Uzbekistan"},"courseKey":null},{"id":"uni-tuit-it-s4","label":{"uz":"Fizika","ru":"Физика","en":"Physics"},"courseKey":"c-physics"}],"admission":{"url":"https://admission.tuit.uz","academicYear":"","checkedOn":"2026-11-03","status":"needs_review","note":"To be verified: TUIT’s own sites (admission.tuit.uz, tuit.uz) announce 2026/2027 admission but list no faculties and no subjects per direction (the only direction list is for 2023/2024, and the directions page returns 404). Mathematics and Physics come from the State Testing Centre directory, which states no year."},"admissionOk":false},{"id":"uni-tuit-business","universityId":"uni-tuit","program":{"uz":"Iqtisodiyot, biznesni boşqariş, marketing, logistika","ru":"Экономика, управление бизнесом, маркетинг, логистика","en":"Economics, Business Management, Marketing, Logistics"},"directionIds":[],"name":{"uz":"TUIT Iqtisodiyot, biznesni boşqariş, marketing, logistika tayyorgarligi","ru":"TUIT: подготовка — Экономика, управление бизнесом, маркетинг, логистика","en":"TUIT Economics, Business Management, Marketing, Logistics Preparation"},"description":{"uz":"TUIT “Iqtisodiyot, biznesni boşqariş, marketing, logistika” uçun rasmiy sahifada körsatilgan talablar böyiça tayyorgarlik. Kurslar — şu fanlar böyiça ILMORA oflayn kurslari; paket universitet bilan rasmiy boğliq emas.","ru":"Подготовка по требованиям, указанным на официальной странице TUIT для «Экономика, управление бизнесом, маркетинг, логистика». Курсы — офлайн-курсы ILMORA по этим предметам; пакет официально не связан с университетом.","en":"Preparation for the requirements TUIT states on its official page for Economics, Business Management, Marketing, Logistics. The courses are ILMORA offline courses for these subjects; the package is not officially affiliated with the university."},"slots":[{"id":"uni-tuit-business-s1","label":{"uz":"Ona tili (özbek, rus yoki qoraqalpoq)","ru":"Родной язык (узбекский, русский или каракалпакский)","en":"Native language (Uzbek, Russian or Karakalpak)"},"courseKey":null},{"id":"uni-tuit-business-s2","label":{"uz":"Matematika (majburiy fan va yönaliş fani)","ru":"Математика (обязательный и профильный предмет)","en":"Mathematics (mandatory and direction subject)"},"courseKey":"c-algebra"},{"id":"uni-tuit-business-s3","label":{"uz":"Özbekiston tarixi","ru":"История Узбекистана","en":"History of Uzbekistan"},"courseKey":null},{"id":"uni-tuit-business-s4","label":{"uz":"Çet tili (tili sahifada körsatilmagan)","ru":"Иностранный язык (язык на странице не указан)","en":"Foreign language (language not named on the page)"},"courseKey":"c-general-english"}],"admission":{"url":"https://admission.tuit.uz","academicYear":"","checkedOn":"2026-11-03","status":"needs_review","note":"To be verified: TUIT’s own sites name no subjects for 2026/2027; Mathematics and a foreign language come from the State Testing Centre directory, which states no year."},"admissionOk":false}]$pkg$::jsonb;
  stored jsonb;
  unis jsonb;
  p jsonb;
  s jsonb;
  slots jsonb;
  dirs jsonb;
  cid text;
  ready boolean;
  seen text[];
  added jsonb := '[]'::jsonb;
  published integer := 0;
BEGIN
  SELECT "tenantId" INTO t FROM "Course" WHERE "id" = 'c-general-english' AND "deletedAt" IS NULL;
  IF t IS NULL THEN
    RAISE NOTICE 'package sync: no ILMORA catalog in this database, nothing to do';
    RETURN;
  END IF;
  SELECT COALESCE("data"->'presets', '[]'::jsonb), COALESCE("data"->'universities', '[]'::jsonb) INTO stored, unis FROM "SiteConfig" WHERE "tenantId" = t;
  IF stored IS NULL OR jsonb_typeof(stored) <> 'array' OR jsonb_typeof(unis) <> 'array' THEN
    RAISE NOTICE 'package sync: no site settings with a package list, nothing to do';
    RETURN;
  END IF;

  FOR p IN SELECT v FROM jsonb_array_elements(seed) AS x(v) LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(stored) AS x(v) WHERE x.v->>'id' = p->>'id');
    CONTINUE WHEN NOT EXISTS (SELECT 1 FROM jsonb_array_elements(unis) AS u(v) WHERE u.v->>'id' = p->>'universityId');
    -- only directions the stored university has (an admin may have edited its faculties)
    SELECT COALESCE(jsonb_agg(d.v), '[]'::jsonb) INTO dirs FROM jsonb_array_elements_text(p->'directionIds') AS d(v)
      WHERE EXISTS (
        SELECT 1 FROM jsonb_array_elements(unis) AS u(v), jsonb_array_elements(COALESCE(u.v->'faculties', '[]'::jsonb)) AS f(v), jsonb_array_elements(COALESCE(f.v->'directions', '[]'::jsonb)) AS dd(v)
        WHERE u.v->>'id' = p->>'universityId' AND dd.v->>'id' = d.v);
    slots := '[]'::jsonb;
    ready := jsonb_array_length(p->'slots') > 0;
    seen := ARRAY[]::text[];
    FOR s IN SELECT v FROM jsonb_array_elements(p->'slots') AS x(v) LOOP
      cid := NULL;
      IF s->>'courseKey' IS NOT NULL THEN
        SELECT c."id" INTO cid FROM "Course" c
          WHERE c."tenantId" = t AND c."deletedAt" IS NULL AND c."learningFormat" = 'OFFLINE'
            AND (c."id" = s->>'courseKey' OR c."slug" = regexp_replace(s->>'courseKey', '^c-', ''))
          ORDER BY (c."id" = s->>'courseKey') DESC LIMIT 1;
      END IF;
      IF cid IS NULL THEN
        ready := false;
      ELSIF NOT EXISTS (
        SELECT 1 FROM "Course" c WHERE c."id" = cid AND c."status" = 'PUBLISHED' AND c."visibility" = 'PUBLIC'
          AND EXISTS (SELECT 1 FROM "Group" g WHERE g."courseId" = c."id" AND g."deletedAt" IS NULL)) THEN
        ready := false;
      END IF;
      IF cid IS NOT NULL THEN
        IF cid = ANY(seen) THEN ready := false; END IF;
        seen := seen || cid;
      END IF;
      slots := slots || jsonb_build_array(
        jsonb_build_object('id', s->'id', 'label', s->'label', 'courseId', cid)
        || CASE WHEN (s->>'optional')::boolean IS TRUE THEN '{"optional":true}'::jsonb ELSE '{}'::jsonb END);
    END LOOP;
    added := added || jsonb_build_array(jsonb_build_object(
      'id', p->'id', 'universityId', p->'universityId', 'program', p->'program', 'directionIds', dirs,
      'name', p->'name', 'description', p->'description', 'slots', slots, 'admission', p->'admission',
      'enabled', ready AND (p->>'admissionOk')::boolean));
    IF ready AND (p->>'admissionOk')::boolean THEN published := published + 1; END IF;
  END LOOP;

  IF jsonb_array_length(added) = 0 THEN
    RAISE NOTICE 'package sync: all packages already present (or their universities are missing), nothing to do';
    RETURN;
  END IF;
  IF jsonb_array_length(stored) + jsonb_array_length(added) > 150 THEN
    RAISE NOTICE 'package sync: more than 150 packages would be stored, nothing added';
    RETURN;
  END IF;

  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'package-sync-20261107-SiteConfig', t, 'content.sync', 'SiteConfig', t,
      jsonb_build_object('version', "version", 'presets', "data"->'presets'),
      jsonb_build_object('addedPackages', (SELECT jsonb_agg(a.v->>'id') FROM jsonb_array_elements(added) AS a(v)), 'published', published),
      'University Preparation: researched packages added (published only when verified and every course is available)'
    FROM "SiteConfig" WHERE "tenantId" = t
    ON CONFLICT ("id") DO NOTHING;
    UPDATE "SiteConfig" SET "data" = jsonb_set("data", '{presets}', stored || added), "version" = "version" + 1, "updatedAt" = CURRENT_TIMESTAMP
      WHERE "tenantId" = t;
    RAISE NOTICE 'package sync: % packages added, % of them published', jsonb_array_length(added), published;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'package sync failed and was rolled back: %', SQLERRM;
  END;
END
$sync$;
